ecular Modeling and Design\nState Key Laboratory of Molecular Reaction Dynamics\nDalian Institute of Chemical Physics\nChinese Academy of Science\n457 Zhongshan Road, Dalian 116023, China", "authorship_id": "69902e18-f5a3-48d8-a591-2d9cbe4dcbeb", "new_id": "d4573ca8-d3a8-5177-a99a-7a676ad639e7"}]$audit$::jsonb) AS x(old_id uuid,publication_id uuid,organization_id uuid,organization_name text,person_id uuid,parent_relation_id uuid,raw_affiliation text,authorship_id uuid,new_id uuid);
DO $$ BEGIN
 IF (SELECT count(*) FROM affiliation_conversion) <> 135 THEN RAISE EXCEPTION 'Unexpected mapping count'; END IF;
 IF EXISTS (SELECT 1 FROM affiliation_conversion m
 LEFT JOIN smartlib.relation_assertion old ON old.relation_id=m.old_id
 LEFT JOIN smartlib.relation_assertion parent ON parent.relation_id=m.parent_relation_id
 LEFT JOIN smartlib.publication_authorship a ON a.publication_authorship_id=m.authorship_id
 WHERE old.predicate IS DISTINCT FROM 'publication.affiliated_with'
 OR old.subject_id IS DISTINCT FROM m.publication_id OR old.object_id IS DISTINCT FROM m.organization_id
 OR NOT (old.attributes->'authors' @> jsonb_build_array(m.person_id::text))
 OR parent.subject_id IS DISTINCT FROM m.person_id OR parent.context_object_id IS DISTINCT FROM m.publication_id
 OR parent.attributes->>'raw_affiliation' IS DISTINCT FROM m.raw_affiliation
 OR a.person_object_id IS DISTINCT FROM m.person_id OR a.publication_id IS DISTINCT FROM m.publication_id
 OR a.verification_status='rejected') THEN RAISE EXCEPTION 'Source evidence mismatch'; END IF;
 IF EXISTS (SELECT 1 FROM smartlib.relation_assertion r WHERE r.predicate='publication.affiliated_with'
 AND r.review_state IN ('pending','approved') AND r.system_to='infinity'
 AND r.relation_id NOT IN (SELECT old_id FROM affiliation_conversion)) THEN RAISE EXCEPTION 'Unmapped paper affiliation exists'; END IF;
END $$;
INSERT INTO smartlib.relation_assertion(relation_id,subject_id,predicate,object_id,fact_class,confidence,visibility,license_tags,review_state,created_by,context_object_id,attributes)
SELECT m.new_id,m.person_id,'person.affiliated_with',m.organization_id,'literature_fact',p.confidence,p.visibility,p.license_tags,'pending',p.created_by,m.publication_id,
 jsonb_build_object('source','cas-person-affiliation-conversion-20260911','rule_version','author-specific-affiliation-v1',
 'publication_id',m.publication_id::text,'raw_affiliation',m.raw_affiliation,'mapping_method','explicit_author_list_and_author_affiliation_text',
 'needs_confirmation',true,'provisional_best_effort',false,'assignments',jsonb_build_array(jsonb_build_object('replaces_relation_id',m.old_id::text,'source_author_relation_id',m.parent_relation_id::text,'organization_id',m.organization_id::text)))
FROM affiliation_conversion m JOIN smartlib.relation_assertion p ON p.relation_id=m.parent_relation_id
ON CONFLICT(relation_id) DO NOTHING;
INSERT INTO smartlib.publication_relation_provenance(relation_id,publication_authorship_id)
SELECT new_id,authorship_id FROM affiliation_conversion ON CONFLICT(relation_id) DO NOTHING;
INSERT INTO smartlib.relation_evidence(relation_id,evidence_id)
SELECT m.new_id,e.evidence_id FROM affiliation_conversion m JOIN smartlib.relation_evidence e ON e.relation_id IN(m.old_id,m.parent_relation_id)
ON CONFLICT DO NOTHING;
DO $$ BEGIN
 IF EXISTS (SELECT 1 FROM affiliation_conversion m LEFT JOIN smartlib.relation_assertion r ON r.relation_id=m.new_id
 WHERE r.predicate IS DISTINCT FROM 'person.affiliated_with' OR r.subject_id IS DISTINCT FROM m.person_id
 OR r.context_object_id IS DISTINCT FROM m.publication_id OR r.object_id IS DISTINCT FROM m.organization_id
 OR r.review_state NOT IN ('pending','approved') OR r.system_to<>'infinity') THEN RAISE EXCEPTION 'Conversion incomplete'; END IF;
END $$;
UPDATE smartlib.relation_assertion SET review_state='superseded'
WHERE relation_id IN(SELECT old_id FROM affiliation_conversion) AND review_state IN('pending','approved');
UPDATE smartlib.relation_predicate_definition SET lifecycle_state='retired',replacement_predicate='person.affiliated_with',
 description='已停用：必须依据具体作者及论文上下文建立 person.affiliated_with，不允许论文直接关联机构。',updated_at=clock_timestamp()
WHERE predicate='publication.affiliated_with';
SET CONSTRAINTS ALL IMMEDIATE;
SELECT count(*) AS converted_author_relations,count(DISTINCT publication_id) AS papers FROM affiliation_conversion;
COMMIT;
